import cpmpy as cp
import json

# Data
X = -1
game_data = [
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

# Model definition
model = cp.Model()

# Decision Variables: mine variables for X cells, 0 for clues
rows = len(game_data)
cols = len(game_data[0]) if rows > 0 else 0
mines = []
for i in range(rows):
    mine_row = []
    for j in range(cols):
        if game_data[i][j] == X:
            mine_row.append(cp.BoolVar(name=f"mines_{i}_{j}"))
        else:
            mine_row.append(0)  # Clue cells are not mines
    mines.append(mine_row)

# Constraints for each clue cell
for i in range(rows):
    for j in range(cols):
        clue_val = game_data[i][j]
        if clue_val != X:
            adjacent_vars = []
            for di in (-1, 0, 1):
                for dj in (-1, 0, 1):
                    if di == 0 and dj == 0:
                        continue  # Skip current cell
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < cols:
                        adjacent_vars.append(mines[ni][nj])
            model += (cp.sum(adjacent_vars) == clue_val)

# Solve and print
if model.solve():
    solution_mines = []
    for i in range(rows):
        row = []
        for j in range(cols):
            if isinstance(mines[i][j], cp.BoolVar):
                row.append(int(mines[i][j].value()))
            else:
                row.append(0)
        solution_mines.append(row)
    print(json.dumps({"mines": solution_mines}, indent=4))
else:
    print("No solution found.")
