import cpmpy as cp
import json

# Data
n_teams = 8
n_weeks = 2 * (n_teams - 1)
n_periods = n_teams // 2

# Model definition
model = cp.Model()

# Decision Variables
home = cp.intvar(0, n_teams-1, shape=(n_weeks, n_periods), name="home")
away = cp.intvar(0, n_teams-1, shape=(n_weeks, n_periods), name="away")

# Constraints

# Each team plays exactly once per week (home or away)
for w in range(n_weeks):
    all_teams = [home[w,p] for p in range(n_periods)] + [away[w,p] for p in range(n_periods)]
    model += cp.AllDifferent(all_teams)

# Each team plays at most twice in the same period across all weeks
for p in range(n_periods):
    for t in range(n_teams):
        model += cp.sum([(home[w,p] == t) + (away[w,p] == t) for w in range(n_weeks)]) <= 2

# Each pair plays exactly once home and once away
for i in range(n_teams):
    for j in range(n_teams):
        if i != j:
            model += cp.sum([(home[w,p] == i) & (away[w,p] == j) for w in range(n_weeks) for p in range(n_periods)]) == 1

# Home and away teams must be different in each period
for w in range(n_weeks):
    for p in range(n_periods):
        model += home[w,p] != away[w,p]

# Solve and print
if model.solve():
    solution = {
        'home': home.value().tolist(),
        'away': away.value().tolist()
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
