import cpmpy as cp
import json

n = 8  # Number of words to find

model = cp.Model()

# Create words as 8x8 matrix of 0-3 variables (A,C,G,T)
words = [[cp.intvar(0, 3, name=f'w_{w}_{i}') for i in range(8)] for w in range(n)]

# Each word has exactly 4 C (1) or G (2)
for word in words:
    model += sum((c == 1) | (c == 2) for c in word) == 4

# All distinct pairs differ in at least 4 positions
for i in range(n):
    for j in range(i + 1, n):
        model += sum(words[i][k] != words[j][k] for k in range(8)) >= 4

# All pairs (including same) satisfy reverse-complement distance >=4
for x_idx in range(n):
    x = words[x_idx]
    for y_idx in range(n):
        y = words[y_idx]
        # Compare x reversed with y complemented (3 - y[i])
        model += sum(x[7 - i] != (3 - y[i]) for i in range(8)) >= 4

# Solve and format output
if model.solve():
    # Convert integer values to DNA letters
    letter_map = {0: 'A', 1: 'C', 2: 'G', 3: 'T'}
    solution = {
        'words': [
            ''.join([letter_map[var.value()] for var in word])
            for word in words
        ]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
